const COUNTRY = { NOR:["Norway","🇳🇴"], SWE:["Sweden","🇸🇪"], FIN:["Finland","🇫🇮"], USA:["USA","🇺🇸"], GBR:["Great Britain","🇬🇧"], ITA:["Italy","🇮🇹"], FRA:["France","🇫🇷"], GER:["Germany","🇩🇪"], SUI:["Switzerland","🇨🇭"], AUT:["Austria","🇦🇹"], CAN:["Canada","🇨🇦"], LAT:["Latvia","🇱🇻"],
  CZE:["Czechia","🇨🇿"], ESP:["Spain","🇪🇸"], SLO:["Slovenia","🇸🇮"], EST:["Estonia","🇪🇪"], POL:["Poland","🇵🇱"],
  AND:["Andorra","🇦🇩"], CHN:["China","🇨🇳"], AUS:["Australia","🇦🇺"], JPN:["Japan","🇯🇵"], IRL:["Ireland","🇮🇪"],
  ARG:["Argentina","🇦🇷"], KOR:["South Korea","🇰🇷"], TPE:["Chinese Taipei",""], AIN:["Individual Neutral Athlete",""] };

const titleCase = s => s.toLowerCase().replace(/(^|[\s-])(\S)/g, (m, a, b) => a + b.toUpperCase());

// Builds the classic game's name pool: World Cup names, FIS registers, IKEA names.
function buildClassicPool() {
  const pool = [
    ...SKIERS.map(([n, full, c, fact]) => ({ kind: "skier", tier: "wc", n, full, c, fact })),

    ...IKEA.map(([n, type, fact]) => ({ kind: "ikea", n, type, fact })),
  ];
  {
    // FIS registers: skip any surname already used by a World Cup skier or IKEA product.
    const taken = new Set(pool.map(q => q.n));
    [[FIS_SWE, "SWE"], [FIS_NOR, "NOR"]].forEach(([list, c]) => list.forEach(([n, first, yr, club]) => {
      if (taken.has(n)) return;
      taken.add(n);
      pool.push({
        kind: "skier", tier: "fis", n, full: `${first} ${titleCase(n)}`, c,
        fact: `Active FIS racer, born ${yr}.${club ? ` Skis for ${club}.` : ""}`,
      });
    }));
    // Name meanings from the IKEA Dictionary, used as the fact on the price tag.
    const meaning = new Map(IKEA_DICT.map(([n, cat, m]) => [n, { cat, m }]));
    const dictFact = n => {
      const d = meaning.get(n);
      if (!d) return "";
      if (d.cat === "w") {
        if (!d.m) return "A Swedish word.";
        return d.m.startsWith("slang ") ? `Swedish slang for "${d.m.slice(6)}".` : `Swedish for "${d.m}".`;
      }
      if (d.cat === "n") return "Also a Scandinavian first name.";
      if (d.cat === "p") return "Named after a place in the Nordic countries.";
      return "";
    };
    pool.forEach(q => { if (q.kind === "ikea" && !q.fact) q.fact = dictFact(q.n); });
    // A skier whose surname is also an IKEA name becomes a "both" question: either answer counts.
    const markBoth = (n, type) => {
      const s = pool.find(q => q.n === n && q.kind === "skier");
      if (s && !s.both) s.both = { type, fact: dictFact(n) };
    };
    IKEA_SERIES.forEach(n => {
      if (taken.has(n)) return markBoth(n, "Product series");
      taken.add(n);
      pool.push({ kind: "ikea", n, type: "Product series", fact: dictFact(n) });
    });
    IKEA_DICT.forEach(([n]) => {
      if (taken.has(n)) return markBoth(n, "IKEA product name");
      taken.add(n);
      pool.push({ kind: "ikea", n, type: "IKEA product name", fact: dictFact(n) });
    });
  }
  return pool;
}


// FIS Cross-Country World Cup 2025/26 final standings (fis-ski.com cup standings, Nov 2026).
